def word_wrap(text, width):
    words = text.split()
    wrapped = []
    current_line = ''
    for word in words:
        if len(current_line) + len(word) + (1 if current_line else 0) <= width:
            current_line += (current_line and ' ' or '') + word
        else:
            wrapped.append(current_line)
            current_line = word
    if current_line:
        wrapped.append(current_line)
    return wrapped if len(' '.join(wrapped)) <= width else [text]
